// Code generated by `caf gen telemetry`. DO NOT EDIT.
//
// the OpenTelemetry setup: the attribute allowlists, the prohibition on
// unbounded identifiers, the resource attributes, the span-name bound,
// the endpoint variable and the no-op path.
//
// WHAT IS DERIVED AND WHAT IS NOT, because a generated file that does not say
// which half of it is an instruction from core is an instruction from whoever
// last touched the generator.
//
// Derived, read out of the cafaye core telemetry contract vendored at
// cafaye/internal/contract/schemas/telemetry/ and pinned there by sha256:
// the three per-signal attribute allowlists and their value vocabularies, the
// names core refuses as a measurement attribute, the resource attributes, the
// error.type vocabulary, the span-name grammar, the OTEL_SDK_DISABLED switch, the three per-signal switches, and the four negative
// properties of the no-op path.
//
// From the manifest: the service name ("gateway") and the language, which is what decided that
// Go was the right file to write.
//
// Written down here, and not derived from anything, because core's schemas
// constrain the shape of these values and do not state them: the namespace
// every cafaye service groups under ("cafaye"), and the address of the
// collector that ships with the local stack ("http://otel-collector:4317"). core's docs/observability.md and its
// examples/valid/telemetry/otel-endpoint.json agree on both; they are the
// fleet's documented values, not this generator's invention.
//
// To change any of it, change cafaye.yml or change core, and run
// `caf gen telemetry -force` again. The test beside this file is
// the thing that notices you did not.

package telemetry

import (
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

// The three signals, named as core names them. There is no fourth: a signal
// nobody has allowlisted has no default-deny list to fall back to, and one
// named here without a list would be a signal whose contents are undefined.
const (
	SignalTraces  = "traces"
	SignalMetrics = "metrics"
	SignalLogs    = "logs"
)

// ---------------------------------------------------------------------------
// identity
// ---------------------------------------------------------------------------

// ServiceName is the emitting service: the manifest's `name`, and the
// mandatory prefix of every span this process creates. An unprefixed span name
// says what happened and not who did it, so a fleet-wide query has to guess
// which of six services to attribute it to.
const ServiceName = "gateway"

// Namespace is what this service groups under in a backend. It is what lets one
// collector show the fleet as one thing rather than as six unrelated services,
// and it is a Stable OpenTelemetry resource attribute rather than a cafaye
// invention.
const Namespace = "cafaye"

// ---------------------------------------------------------------------------
// the endpoint contract, and the no-op path
// ---------------------------------------------------------------------------
//
// ^[A-Z][A-Z0-9]*_OTEL_ENDPOINT$ is the only contract: the shape the
// variable name has to have. The shipped collector is just the default value of
// it, so a developer with nothing configured sees real traces — observability is
// on by default — and a self-hoster who already runs a backend points this at
// it, which is a supported deployment and not a degraded mode.

const (
	// EndpointVariable is `<SERVICE>_OTEL_ENDPOINT`: the name a reader
	// can know without reading this file.
	EndpointVariable = "GATEWAY_OTEL_ENDPOINT"

	// DefaultEndpoint is the collector that ships with the local stack. It is a
	// default value and not a constant of behavior: changing it changes where a
	// developer with no configuration sends their telemetry, which is the point.
	DefaultEndpoint = "http://otel-collector:4317"
)

// The switches, and what turning each of them off means. The global one is the
// OpenTelemetry specification's own kill switch, and it is what the no-op path
// is implemented with rather than a cafaye reimplementation of "disabled": six
// languages re-implementing one word is how six services acquire six different
// definitions of it, and the difference between them is somebody's production
// incident.
//
// The other three are the standard per-signal exporters. All four are named
// here, and not just the global one, because a no-op that only covers traces is
// a service that still phones home for metrics — the failure discovered by a
// customer's invoice rather than by a test.
const (
	SwitchSDKDisabled     = "OTEL_SDK_DISABLED"
	SwitchTracesExporter  = "OTEL_TRACES_EXPORTER"
	SwitchMetricsExporter = "OTEL_METRICS_EXPORTER"
	SwitchLogsExporter    = "OTEL_LOGS_EXPORTER"
)

// Endpoint is where OTLP goes.
//
// GATEWAY_OTEL_ENDPOINT wins over the standard `OTEL_EXPORTER_OTLP_ENDPOINT`, which
// is honored as a fallback so the service also works with generic OTel tooling.
// That precedence is written down rather than left to be discovered, because a
// contract with an undocumented precedence order is a bug report.
func Endpoint() string {
	if endpoint := os.Getenv(EndpointVariable); endpoint != "" {
		return endpoint
	}
	if endpoint := os.Getenv("OTEL_EXPORTER_OTLP_ENDPOINT"); endpoint != "" {
		return endpoint
	}
	return DefaultEndpoint
}

// Enabled reports whether any signal will be exported, and a caller that wants
// one signal asks SignalEnabled.
//
// It is false for the whole process on `OTEL_SDK_DISABLED=true` and for
// nothing else: a service with traces switched off and metrics switched on is a
// legitimate configuration of the standard variables, not a half-installed one.
func Enabled() bool {
	if switchedOff(SwitchSDKDisabled, "true") {
		return false
	}
	return SignalEnabled(SignalTraces) || SignalEnabled(SignalMetrics) || SignalEnabled(SignalLogs)
}

// SignalEnabled reports whether one signal's exporter is on.
//
// The global switch is consulted here and not only in Enabled, because a caller
// asking about one signal is asking whether that signal will be exported — and
// the answer on OTEL_SDK_DISABLED=true is no for all three. An earlier draft of
// this file checked only the per-signal switch and the suite beside it caught
// it, which is the argument for generating the suite from the same contract
// tables rather than writing it later.
func SignalEnabled(signal string) bool {
	if switchedOff(SwitchSDKDisabled, "true") {
		return false
	}
	switch signal {
	case SignalTraces:
		return !switchedOff(SwitchTracesExporter, "none")
	case SignalMetrics:
		return !switchedOff(SwitchMetricsExporter, "none")
	case SignalLogs:
		return !switchedOff(SwitchLogsExporter, "none")
	}
	return false
}

// NoOpReason is one line for a startup log, and only on the path where telemetry
// is actually off.
//
// Silence is the contract: a service that logs a warning per export attempt
// fills its own log store with the fact that telemetry is off, which is how a
// self-hoster discovers that turning it off is not supported — the opposite of
// the intent. One line at startup is not that, and it is the difference between
// "telemetry is off" and "telemetry is broken", which look identical from
// outside. Empty means telemetry is on.
func NoOpReason() string {
	switch {
	case switchedOff(SwitchSDKDisabled, "true"):
		return SwitchSDKDisabled + "=true"
	case !Enabled():
		return "every " + SwitchTracesExporter + ", " + SwitchMetricsExporter +
			" and " + SwitchLogsExporter + " is none"
	}
	return ""
}

// switchedOff is case-insensitive on purpose. The OTel environment variables are
// read by six SDKs and typed by a person at a terminal, and "TRUE" is a
// misspelling that should mean off rather than on.
func switchedOff(name, value string) bool {
	return strings.EqualFold(os.Getenv(name), value)
}

// ---------------------------------------------------------------------------
// the per-signal allowlists
// ---------------------------------------------------------------------------
//
// Default-deny on every signal. An attribute that is not on its signal's list is
// not emitted, so an attribute added in a hurry is dropped rather than shipped —
// and the refusal is loud enough to find, which is the other half of the reason:
// an attribute nobody declared is usually an attribute somebody typed, and a
// silently-dropped attribute is a broken dashboard nobody debugs.
//
// The three lists are different lists and that is deliberate. Traces carry the
// status code; metrics carry the status CLASS, because a metric multiplied by
// five hundred codes and every route is how a service reaches the cardinality cap
// below in a week, and `4xx` answers the question a dashboard actually asks.
// Logs carry the least of all: they are the highest-volume signal and the one a
// support engineer reads with the least context.

// Kind is the JSON type of an attribute's value.
type Kind string

// The kinds core's allowlists use. Boolean and array are not among them: core
// writes `type` as a list on the two fields that accept more than one
// (a span-naming document's target, a span's status), and neither is an
// allowlisted measurement, so no emitted attribute needs them and a generated
// file that declared them would be declaring a vocabulary nobody uses.
const (
	KindString  Kind = "string"
	KindInteger Kind = "integer"
)

// Attribute is one entry of a per-signal allowlist: the name, and what the name
// is a fact ABOUT.
//
// The value constraints are carried rather than the name alone because an
// allowlist that says only which names are legal is half the rule.
// `db.operation` is a closed six-verb vocabulary and `error.type` a
// closed one of 13; a check that looked only at the name would
// accept `db.operation: "DROP TABLE users"`, hand it to a collector that
// drops it, and leave a drill-down that silently undercounts with no error
// anywhere.
type Attribute struct {
	// Name is the attribute as core spells it, dotted OpenTelemetry style.
	Name string
	// Kind is the JSON type its value has.
	Kind Kind
	// Values is the closed vocabulary, for the attributes core gives one. Empty
	// for the attributes bounded by length or pattern instead.
	Values []string
	// Min and Max bound a numeric attribute, and both are zero for an attribute
	// with no numeric constraint — which is every string attribute, so "zero
	// means unconstrained" is a fact about this struct rather than an assumption
	// about the data.
	Min, Max int64
	// MaxLength bounds a string attribute, and is zero for one core bounds
	// another way.
	MaxLength int
	// Pattern is core's own regex, compiled once at init. Nil where core writes no
	// pattern, and an unconstrained attribute is a legitimate answer here:
	// `service.version` is bounded by MaxLength alone.
	Pattern *regexp.Regexp
}

